import{_ as s,o as i,c as a,ag as t}from"./chunks/framework.BpFM782D.js";const c=JSON.parse('{"title":"find-skills","description":"","frontmatter":{},"headers":[],"relativePath":"skills/find-skills.md","filePath":"skills/find-skills.md"}'),e={name:"skills/find-skills.md"};function d(n,l,r,o,h,k){return i(),a("div",null,[...l[0]||(l[0]=[t(`<h1 id="find-skills" tabindex="-1">find-skills <a class="header-anchor" href="#find-skills" aria-label="Permalink to &quot;find-skills&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>find-skills</td></tr><tr><td>說明</td><td>搜尋可用的 skill。根據關鍵字或場景找到最適合的 skill。</td></tr><tr><td>來源目錄</td><td><code>skills/find-skills/</code></td></tr></tbody></table><hr><h1 id="搜尋-skills" tabindex="-1">搜尋 Skills <a class="header-anchor" href="#搜尋-skills" aria-label="Permalink to &quot;搜尋 Skills&quot;">​</a></h1><p>此 skill 幫助你從開放的 agent skills 生態系統中發現和安裝 skills。</p><h2 id="使用時機" tabindex="-1">使用時機 <a class="header-anchor" href="#使用時機" aria-label="Permalink to &quot;使用時機&quot;">​</a></h2><p>當使用者：</p><ul><li>詢問「我要怎麼做 X」，而 X 可能有現成的 skill</li><li>說「幫我找 X 的 skill」或「有沒有 X 的 skill」</li><li>問「你可以做 X 嗎」，而 X 是專業功能</li><li>表示有興趣擴展 agent 功能</li><li>想搜尋工具、模板或工作流程</li><li>提到希望在某個領域（設計、測試、部署等）獲得幫助</li></ul><h2 id="什麼是-skills-cli" tabindex="-1">什麼是 Skills CLI？ <a class="header-anchor" href="#什麼是-skills-cli" aria-label="Permalink to &quot;什麼是 Skills CLI？&quot;">​</a></h2><p>Skills CLI（<code>npx skills</code>）是開放 agent skills 生態系統的套件管理器。Skills 是模組化套件，透過專業知識、工作流程和工具擴展 agent 的能力。</p><p><strong>主要命令：</strong></p><ul><li><code>npx skills find [query]</code> — 互動式搜尋或按關鍵字搜尋</li><li><code>npx skills add &amp;lt;package&gt;</code> — 從 GitHub 或其他來源安裝 skill</li><li><code>npx skills check</code> — 檢查 skill 更新</li><li><code>npx skills update</code> — 更新所有已安裝的 skills</li></ul><p><strong>瀏覽 skills：</strong> <a href="https://skills.sh/" target="_blank" rel="noreferrer">https://skills.sh/</a></p><h2 id="如何幫助使用者搜尋-skills" tabindex="-1">如何幫助使用者搜尋 Skills <a class="header-anchor" href="#如何幫助使用者搜尋-skills" aria-label="Permalink to &quot;如何幫助使用者搜尋 Skills&quot;">​</a></h2><h3 id="步驟-1-了解需求" tabindex="-1">步驟 1：了解需求 <a class="header-anchor" href="#步驟-1-了解需求" aria-label="Permalink to &quot;步驟 1：了解需求&quot;">​</a></h3><p>當使用者尋求幫助時，識別：</p><ol><li>領域（例如 React、測試、設計、部署）</li><li>具體任務（例如撰寫測試、建立動畫、審查 PR）</li><li>這是否為常見任務（很可能已有現成 skill）</li></ol><h3 id="步驟-2-搜尋-skills" tabindex="-1">步驟 2：搜尋 Skills <a class="header-anchor" href="#步驟-2-搜尋-skills" aria-label="Permalink to &quot;步驟 2：搜尋 Skills&quot;">​</a></h3><p>用相關查詢執行 find 命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [query]</span></span></code></pre></div><p>範例：</p><ul><li>使用者問「如何讓 React app 更快？」→ <code>npx skills find react performance</code></li><li>使用者問「可以幫我審 PR 嗎？」→ <code>npx skills find pr review</code></li><li>使用者問「我需要建立 changelog」→ <code>npx skills find changelog</code></li></ul><p>命令會回傳結果如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install with npx skills add &amp;lt;owner/repo@skill&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vercel-labs/agent-skills@vercel-react-best-practices</span></span>
<span class="line"><span>└ https://skills.sh/vercel-labs/agent-skills/vercel-react-best-practices</span></span></code></pre></div><h3 id="步驟-3-向使用者展示選項" tabindex="-1">步驟 3：向使用者展示選項 <a class="header-anchor" href="#步驟-3-向使用者展示選項" aria-label="Permalink to &quot;步驟 3：向使用者展示選項&quot;">​</a></h3><p>找到相關 skills 時，向使用者說明：</p><ol><li>Skill 名稱和功能</li><li>安裝命令</li><li>詳細資訊連結</li></ol><h3 id="步驟-4-提供安裝" tabindex="-1">步驟 4：提供安裝 <a class="header-anchor" href="#步驟-4-提供安裝" aria-label="Permalink to &quot;步驟 4：提供安裝&quot;">​</a></h3><p>若使用者想安裝，執行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">owner/repo@skill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-g</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p><code>-g</code> 全域安裝（使用者層級），<code>-y</code> 跳過確認提示。</p><h2 id="常見-skill-類別" tabindex="-1">常見 Skill 類別 <a class="header-anchor" href="#常見-skill-類別" aria-label="Permalink to &quot;常見 Skill 類別&quot;">​</a></h2><table tabindex="0"><thead><tr><th>類別</th><th>搜尋範例</th></tr></thead><tbody><tr><td>網頁開發</td><td>react, nextjs, typescript, css, tailwind</td></tr><tr><td>測試</td><td>testing, jest, playwright, e2e</td></tr><tr><td>DevOps</td><td>deploy, docker, kubernetes, ci-cd</td></tr><tr><td>文件</td><td>docs, readme, changelog, api-docs</td></tr><tr><td>程式碼品質</td><td>review, lint, refactor, best-practices</td></tr><tr><td>設計</td><td>ui, ux, design-system, accessibility</td></tr><tr><td>生產力</td><td>workflow, automation, git</td></tr></tbody></table><h2 id="搜尋提示" tabindex="-1">搜尋提示 <a class="header-anchor" href="#搜尋提示" aria-label="Permalink to &quot;搜尋提示&quot;">​</a></h2><ol><li><strong>使用具體關鍵字</strong>：「react testing」比單純「testing」好</li><li><strong>嘗試替代用詞</strong>：如果「deploy」沒結果，試試「deployment」或「ci-cd」</li><li><strong>檢查熱門來源</strong>：許多 skills 來自 <code>vercel-labs/agent-skills</code> 或 <code>ComposioHQ/awesome-claude-skills</code></li></ol><h2 id="找不到-skills-時" tabindex="-1">找不到 Skills 時 <a class="header-anchor" href="#找不到-skills-時" aria-label="Permalink to &quot;找不到 Skills 時&quot;">​</a></h2><p>若沒有相關 skills：</p><ol><li>告知使用者沒有找到現有 skill</li><li>提供直接協助的方案</li><li>建議使用者建立自己的 skill：<code>npx skills init my-skill</code></li></ol>`,38)])])}const g=s(e,[["render",d]]);export{c as __pageData,g as default};
